        .INIT_RAM_06(256'h50984ffb4f5e4ec04e214d814ce14c404b9e4afb4a5849b4490f486a47c4471d),
        .INIT_RAM_07(256'h59f4596458d4584357b1571e568a55f6556054ca5433539b5303526951cf5134),
        .INIT_RAM_08(256'h627261f1616f60ec60685fe45f5e5ed75e505dc85d3e5cb45c295b9d5b105a82),
        .INIT_RAM_09(256'h69fd698c691a68a7683267bd674766d0665765de656464e9646c63ef637162f2),
